      // something)
      // https://bugs.openjdk.java.net/browse/JDK-8015110
      resetToBegin();
      currentSentence = 0;
      return DONE;
    } else {
      currentSentence = lastSpanCount / 2; // start search from the middle
      moveToSentenceAt(pos, 0, lastSpanCount - 1);
      if (0 == currentSentence) {
        resetToBegin();
        return DONE;
      } else {
        goToStoredSentence(--currentSentence);
        return current();
      }
    }
  }

  private int iteratorBegin() {
    return text.getBeginIndex();
  }

  private void resetToBegin() {
    text.setIndex(text.getBeginIndex());
  }

  private void goToStoredSentence(int index) {
    text.setIndex(sentenceStarts[index]);
